postEvent("view-ready", {

const payload = request.payload || {};
// SPEC-P-ms-formats E4: a .docx name opens, and docx saves, only where the
// manifest says so; everything else keeps its row.
const requiredCapability =
  request.operation === "open" && /\.docx$/i.test(String(payload.name || "")) ? "open-docx"
  : request.operation === "save" && payload.format === "docx" ? "save-docx"
  : OPERATION_CAPABILITIES.get(request.operation);
